package com.servicerca.model; import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="recovery_token") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class RecoveryToken { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(name="token_hash",nullable=false,unique=true,length=64) private String tokenHash; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="used_at") private Instant usedAt; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=Instant.now();} }
